import { expect, test } from "vitest";
import * as fs from "fs";
import * as path from "path";

test("fetch-nodeshim is listed in package.json dependencies", () => {
  const packageJsonPath = path.join(process.cwd(), "package.json");
  const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, "utf-8"));

  expect(packageJson.dependencies).toBeDefined();
  expect(packageJson.dependencies["fetch-nodeshim"]).toBeDefined();
  expect(packageJson.dependencies["fetch-nodeshim"]).toMatch(/^\^1\.1/);
});

test("fetch-nodeshim directory exists in node_modules", () => {
  const nodeshimPath = path.join(process.cwd(), "node_modules", "fetch-nodeshim");
  expect(fs.existsSync(nodeshimPath)).toBe(true);
});

test("fetch-nodeshim has package.json in node_modules", () => {
  const packageJsonPath = path.join(
    process.cwd(),
    "node_modules",
    "fetch-nodeshim",
    "package.json"
  );
  expect(fs.existsSync(packageJsonPath)).toBe(true);
});

test("fetch-nodeshim directory contains files", () => {
  const nodeshimPath = path.join(process.cwd(), "node_modules", "fetch-nodeshim");
